def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    rectangles = []
    frame_cells = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            rs = [x for x, _ in comp]
            cs = [y for _, y in comp]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            if r1 - r0 >= 2 and c1 - c0 >= 2:
                border = set()
                for y in range(c0, c1 + 1):
                    border.add((r0, y))
                    border.add((r1, y))
                for x in range(r0, r1 + 1):
                    border.add((x, c0))
                    border.add((x, c1))
                if set(comp) == border:
                    rectangles.append((color, r0, r1, c0, c1))
                    frame_cells.update(comp)

    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != 0 and (r, c) not in frame_cells:
                counts[color] = counts.get(color, 0) + 1

    for _, r0, r1, c0, c1 in rectangles:
        ir0, ir1, ic0, ic1 = r0 + 1, r1 - 1, c0 + 1, c1 - 1
        cells = [(r, c) for r in range(ir0, ir1 + 1)
                 for c in range(ic0, ic1 + 1)
                 if ((r - ir0) + (c - ic0)) % 2 == 0]
        n = len(cells)
        for color, count in counts.items():
            if count == n:
                for r, c in cells:
                    out[r][c] = color
                break

    return out
